const input = $input.first().json;
const body = input.body || input;
const shipment_id = String(body.shipment_id || "").trim();
const exception_text = String(body.exception_text || "").trim();
const shipments = {
"SHP-1001":{customer_name:"Sample Customer One",customer_email:"customer1@example.com",customer_tier:"premium",status:"In Transit",address:"Sample delivery address, Mumbai",route:"Ahmedabad -> Mumbai",sla_hours_left:48},
"SHP-1002":{customer_name:"Sample Customer Two",customer_email:"customer2@example.com",customer_tier:"standard",status:"Out for Delivery",address:"Sample delivery address, Pune",route:"Surat -> Pune",sla_hours_left:6},
"SHP-1003":{customer_name:"Sample Customer Three",customer_email:"customer3@example.com",customer_tier:"standard",status:"Delivery Attempted",address:"Sample delivery address, Delhi",route:"Vadodara -> Delhi",sla_hours_left:20},
"SHP-1004":{customer_name:"Sample Customer One",customer_email:"customer1@example.com",customer_tier:"premium",status:"Delayed",address:"Sample delivery address, Bengaluru",route:"Ahmedabad -> Bengaluru",sla_hours_left:-5},
"SHP-1005":{customer_name:"Sample Customer Four",customer_email:"customer4@example.com",customer_tier:"premium",status:"Exception",address:"Sample delivery address, Chennai",route:"Rajkot -> Chennai",sla_hours_left:30},
"SHP-1006":{customer_name:"Sample Customer Two",customer_email:"customer2@example.com",customer_tier:"standard",status:"Held",address:"",route:"Surat -> Jaipur",sla_hours_left:10}
};
const missing=[];
if(!shipment_id) missing.push("shipment_id");
if(shipment_id && !shipments[shipment_id]) missing.push("shipment record");
if(!exception_text) missing.push("exception_text");
const shipment=shipments[shipment_id]||null;
if(shipment&&!shipment.address) missing.push("delivery address");
const facts=shipment?{shipment_id,...shipment,sla_breached:shipment.sla_hours_left<0,sla_warn_hours:shipment.customer_tier==="premium"?24:12,sla_at_risk:shipment.sla_hours_left>=0&&shipment.sla_hours_left<=(shipment.customer_tier==="premium"?24:12),escalate_to:shipment.customer_tier==="premium"?"ops-manager":"ops-team"}:{};
const sd=$getWorkflowStaticData("global");
sd.seen=sd.seen||{};
const dedupe_key=shipment_id+"|"+exception_text.toLowerCase().slice(0,60);
const duplicate=!!(sd.seen[dedupe_key]&&(Date.now()-sd.seen[dedupe_key])<24*60*60*1000);
const prompt=[
"You are a logistics delivery-exception analyst. Classify the exception and choose ONE next action.",
"SHIPMENT FACTS (rule-computed; trust these): "+JSON.stringify(facts),
"EXCEPTION REPORT: "+JSON.stringify(exception_text),
"Allowed exception_type: weather_delay, traffic_delay, address_issue, recipient_unavailable, damaged_or_lost, customer_complaint, unknown",
"Allowed action: notify_customer, request_address, escalate_sla, human_review",
"Rules: address_issue -> request_address; weather_delay, traffic_delay, recipient_unavailable with safe SLA -> notify_customer; SLA at risk/breached -> escalate_sla; damaged_or_lost, complaints, unclear/conflicting data -> human_review. Never invent facts.",
'Return JSON only: {"exception_type":"","action":"","confidence":0,"reason":"","new_eta_hint":"","draft_message":""}'
].join("\n");
return [{json:{shipment_id,exception_text,facts,missing,data_missing:missing.length>0,duplicate,dedupe_key,prompt}}];

const previous=$("Lookup Data & Compute Facts").first().json;
const response=$input.first().json;
if(previous.duplicate)return [{json:{timestamp:new Date().toISOString(),shipment_id:previous.shipment_id,exception_type:"duplicate",action:"duplicate_skip",priority:"none",confidence:1,reason:"Same exception was already processed within the last 24 hours.",channel:"none",recipient:"",message:"Duplicate ignored",approval_required:false,record_status:"ignored_duplicate",guardrail_overrides:[]}}];
if(previous.data_missing)return [{json:{timestamp:new Date().toISOString(),shipment_id:previous.shipment_id,exception_type:"unknown",action:"human_review",priority:"high",confidence:0,reason:"Missing data: "+previous.missing.join(", ")+". The agent will not guess.",channel:"human-queue",recipient:"support-lead",message:"",approval_required:true,record_status:"awaiting_human",guardrail_overrides:["missing data"]}}];
let d={};
try{const t=String(response.candidates[0].content.parts[0].text||"");d=JSON.parse(t.slice(t.indexOf("{"),t.lastIndexOf("}")+1));}
catch(e){d={exception_type:"unknown",action:"human_review",confidence:0,reason:"AI output could not be parsed",draft_message:""};}
const allowed=["notify_customer","request_address","escalate_sla","human_review"];
let action=allowed.includes(d.action)?d.action:"human_review";
const overrides=[];
const confidence=Number(d.confidence)||0;
const f=previous.facts;
if(confidence<0.7){action="human_review";overrides.push("confidence below 0.7");}
if(["damaged_or_lost","customer_complaint","unknown"].includes(d.exception_type)){action="human_review";overrides.push("exception type requires human review");}
if(f.sla_breached&&action!=="human_review"){action="escalate_sla";overrides.push("SLA already breached");}
else if(f.sla_at_risk&&action==="notify_customer"){action="escalate_sla";overrides.push("SLA at risk");}
const sd=$getWorkflowStaticData("global");sd.seen=sd.seen||{};if(previous.dedupe_key)sd.seen[previous.dedupe_key]=Date.now();
const priority=f.sla_breached?"critical":((f.sla_at_risk||f.customer_tier==="premium")?"high":"normal");
const customerAction=["notify_customer","request_address"].includes(action);
return [{json:{timestamp:new Date().toISOString(),shipment_id:previous.shipment_id,exception_type:d.exception_type||"unknown",action,priority,confidence,reason:d.reason||"",channel:customerAction?"email-draft":(action==="escalate_sla"?"internal-alert-draft":"human-queue"),recipient:customerAction?f.customer_email:(action==="escalate_sla"?f.escalate_to:"support-lead"),message:customerAction?(d.draft_message||""):"",approval_required:customerAction||action==="human_review",record_status:customerAction?"pending_approval":(action==="human_review"?"awaiting_human":"actioned"),guardrail_overrides:overrides}}];
